'use strict';

const test = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const os = require('os');
const path = require('path');
const L = require('../src/scanners/lockfiles');

// Fixtures are real lockfiles generated by each tool for the same small projects
// (hashes and wheel lists trimmed): react-dom + left-pad + @types/node, and requests + six.
const FX = path.join(__dirname, 'fixtures', 'lockfiles');
const read = (f) => fs.readFileSync(path.join(FX, f), 'utf8');
const ids = (deps) => deps.map(d => `${d.name}@${d.version}`).sort();

const JS = ['@types/node@20.11.0', 'js-tokens@4.0.0', 'left-pad@1.3.0', 'loose-envify@1.4.0',
  'react-dom@18.2.0', 'react@18.2.0', 'scheduler@0.23.2', 'undici-types@5.26.5'];
const PY = ['certifi@2026.10.23', 'charset-normalizer@3.5.2', 'idna@3.20', 'requests@2.31.0', 'six@1.16.0', 'urllib3@2.8.0'];

for (const [file, fn, expected] of [
  ['pnpm-v5.4.yaml', 'parsePnpmLock', JS],
  ['pnpm-v6.0.yaml', 'parsePnpmLock', JS],
  ['pnpm-v9.0.yaml', 'parsePnpmLock', JS],
  ['yarn-classic.lock', 'parseYarnLock', JS],
  ['yarn-berry.lock', 'parseYarnLock', JS],
  ['bun.lock', 'parseBunLock', JS],
  ['poetry.lock', 'parsePoetryLock', PY],
  ['uv.lock', 'parseUvLock', PY],
  ['Pipfile.lock', 'parsePipfileLock', PY],
]) {
  test(`${fn} reads a real ${file}`, () => {
    assert.deepStrictEqual([...new Set(ids(L[fn](read(file))))], expected);
  });
}

test('pnpm: peer suffixes and scoped names', () => {
  const v6 = 'lockfileVersion: \'6.0\'\n\npackages:\n\n  /@scope/a@1.0.0(react@18.2.0):\n    resolution: {integrity: x}\n';
  assert.deepStrictEqual(ids(L.parsePnpmLock(v6)), ['@scope/a@1.0.0']);
  const v5 = 'lockfileVersion: 5.4\n\npackages:\n\n  /@scope/a/1.0.0_react@18.2.0:\n    resolution: {integrity: x}\n';
  assert.deepStrictEqual(ids(L.parsePnpmLock(v5)), ['@scope/a@1.0.0']);
  // importers / snapshots sections are not package entries
  const v9 = "lockfileVersion: '9.0'\n\nimporters:\n\n  .:\n    dependencies: {}\n\nsnapshots:\n\n  b@2.0.0: {}\n";
  assert.deepStrictEqual(L.parsePnpmLock(v9), []);
});

test('yarn: only npm-registry entries are kept', () => {
  const berry = [
    '__metadata:', '  version: 8', '',
    '"a@npm:^1.0.0":', '  version: 1.0.1', '  resolution: "a@npm:1.0.1"', '',
    '"app@workspace:.":', '  version: 0.0.0-use.local', '  resolution: "app@workspace:."', '',
    '"b@patch:b@npm%3A2.0.0#~/.yarn/patches/b.patch":', '  version: 2.0.0', '  resolution: "b@patch:b@npm%3A2.0.0#~/.yarn/patches/b.patch::version=2.0.0"', '',
  ].join('\n');
  assert.deepStrictEqual(ids(L.parseYarnLock(berry)), ['a@1.0.1']);
  const classic = [
    '# yarn lockfile v1', '',
    'alias@npm:real@^2.0.0:', '  version "2.1.0"', '',
    '"x@git+https://example.com/x.git":', '  version "1.0.0-git"', '',
    'y@file:../y:', '  version "1.0.0"', '',
  ].join('\n');
  assert.deepStrictEqual(ids(L.parseYarnLock(classic)), ['real@2.1.0']);
});

test('bun: workspace, link and git entries are skipped', () => {
  const text = `{ // comment
    "lockfileVersion": 1,
    "packages": {
      "a": ["a@1.2.3", "", {}, "sha512-x"],
      "w": ["w@workspace:packages/w"],
      "g": ["g@github:o/g#abc", {}],
    },
  }`;
  assert.deepStrictEqual(ids(L.parseBunLock(text)), ['a@1.2.3']);
});

test('uv: local sources are skipped; Pipfile: only == pins', () => {
  const uv = '[[package]]\nname = "lib"\nversion = "0.1.0"\nsource = { editable = "lib" }\n\n[[package]]\nname = "x"\nversion = "1.0"\nsource = { registry = "https://pypi.org/simple" }\n';
  assert.deepStrictEqual(ids(L.parseUvLock(uv)), ['x@1.0']);
  const pip = JSON.stringify({ default: { a: { version: '==1.0' }, b: { git: 'https://x', ref: 'abc' } }, develop: { c: { version: '==2.0' } } });
  assert.deepStrictEqual(ids(L.parsePipfileLock(pip)), ['a@1.0', 'c@2.0']);
});

test('scan: projects, unparsed binary bun.lockb and parse errors', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'hg-lock-'));
  try {
    const mk = (sub, name, body) => {
      fs.mkdirSync(path.join(dir, sub), { recursive: true });
      const p = path.join(dir, sub, name);
      fs.writeFileSync(p, body);
      return p;
    };
    const pnpm = mk('web', 'pnpm-lock.yaml', read('pnpm-v9.0.yaml'));
    const uv = mk('api', 'uv.lock', read('uv.lock'));
    const lockb = mk('old', 'bun.lockb', Buffer.from([0x23, 0x21, 0, 1]));
    const bad = mk('bad', 'Pipfile.lock', '{ not json');
    const found = new Map([['pnpm-lock.yaml', [pnpm]], ['uv.lock', [uv]], ['bun.lockb', [lockb]], ['Pipfile.lock', [bad]]]);
    const r = L.scan(found);
    assert.deepStrictEqual(r.projects.map(p => [p.project, p.lockfile_type, p.ecosystem, p.total_dependencies]),
      [['web', 'pnpm', 'npm', 8], ['api', 'uv', 'pypi', 6]]);
    assert.deepStrictEqual(r.unparsed.map(u => path.basename(u.lockfile)).sort(), ['Pipfile.lock', 'bun.lockb']);
    assert.match(r.unparsed.find(u => u.lockfile === bad).reason, /^parse error/);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});
